// Client-side search over /assets/search-index.json (generated by build.py).
// Filters (type, grade, topic area) and sort order are kept in the address, so results can be shared.
(async function () {
  const input = document.getElementById('q');
  const results = document.getElementById('results');
  const filterBar = document.getElementById('filters');
  const sortSel = document.getElementById('sort');
  const countEl = document.getElementById('count');
  const params = new URLSearchParams(location.search);
  const filters = { kind: 'all', grade: 'all', area: 'all' };
  for (const k in filters) filters[k] = params.get(k) || 'all';
  sortSel.value = params.get('sort') || 'syllabus';
  input.value = params.get('q') || '';

  let items = [];
  try {
    const res = await fetch('/assets/search-index.json');
    if (!res.ok) throw new Error(res.status);
    items = await res.json();
  } catch (e) {
    results.innerHTML = '<p class="empty">Could not load the search index.</p>';
    return;
  }

  const esc = s => s.replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
  const norm = s => s.toLowerCase().replace(/[^a-z0-9 ]+/g, ' ');
  const LABEL = { notes: 'Notes', mcq: 'MCQ', paper: 'Model paper' };
  const SORTS = {
    syllabus: (a, b) => (a.grade !== b.grade ? (a.grade === 'XI' ? -1 : 1) : a.order - b.order || a.title.localeCompare(b.title)),
    new: (a, b) => b.date.localeCompare(a.date) || a.title.localeCompare(b.title),
    az: (a, b) => a.title.localeCompare(b.title),
  };

  function render() {
    // Every word must appear somewhere in the lesson's title, chapter, topics or type.
    const words = norm(input.value).split(/\s+/).filter(Boolean);
    const hits = items.filter(x => Object.keys(filters).every(k => filters[k] === 'all' || x[k] === filters[k]) &&
      words.every(w => x.haystack.includes(w))).sort(SORTS[sortSel.value] || SORTS.syllabus);
    results.innerHTML = hits.map(x => `
      <article class="card kind-${esc(x.kind)}">
        <div><span class="badge ${esc(x.kind)}">${LABEL[x.kind] || ''}</span></div>
        <h3><a href="${esc(x.url)}">${esc(x.title)}</a></h3>
        <div class="meta">Grade ${esc(x.grade)} · ${esc(x.chapter)}</div>
      </article>`).join('') ||
      '<p class="empty">No matching lessons yet. Try a chapter name such as “waves” or “heat”, or clear a filter.</p>';
    countEl.textContent = `${hits.length} result${hits.length === 1 ? '' : 's'}`;
    filterBar.querySelectorAll('[data-group]').forEach(g =>
      g.querySelectorAll('button').forEach(b => b.setAttribute('aria-pressed', b.dataset.value === filters[g.dataset.group])));
    const qs = new URLSearchParams();
    if (input.value.trim()) qs.set('q', input.value.trim());
    for (const k in filters) if (filters[k] !== 'all') qs.set(k, filters[k]);
    if (sortSel.value !== 'syllabus') qs.set('sort', sortSel.value);
    history.replaceState(null, '', qs.toString() ? '?' + qs : location.pathname);
  }

  // Report what people search for (once they pause typing), so missing topics show up in analytics.
  let timer;
  function trackSearch() {
    clearTimeout(timer);
    const q = norm(input.value).trim().slice(0, 60);
    if (q.length >= 3 && window.pdTrack) timer = setTimeout(() => window.pdTrack('Search', { query: q }), 1500);
  }

  input.addEventListener('input', () => { render(); trackSearch(); });
  document.getElementById('search-form').addEventListener('submit', e => { e.preventDefault(); render(); });
  sortSel.addEventListener('change', render);
  filterBar.addEventListener('click', e => {
    const b = e.target.closest('button[data-value]');
    if (!b) return;
    const group = b.closest('[data-group]').dataset.group;
    filters[group] = b.dataset.value;
    // Model papers cover every topic area, so the two filters can't both apply.
    if (group === 'kind' && b.dataset.value === 'paper') filters.area = 'all';
    if (group === 'area' && b.dataset.value !== 'all' && filters.kind === 'paper') filters.kind = 'all';
    render();
  });
  render();
  trackSearch();
})();
